const rows = $input.all();
function normalize(text) {
  return text
    .toLowerCase()
    .replace(/[^\w\s]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

const userQ = normalize(
  $('When chat message received').first().json.chatInput
);


let bestMatch = null;
let score = 0;

let faqs = "";

for (const item of rows) {
  const q= item.json.prompts;
  const a = item.json.responses;

  if (!a) continue;

  faqs += `${q}:${a},`;

const hits = normalize(q)
  .split(" ")
  .filter(w => userQ.includes(w)).length;


  if (hits > score) {
    score = hits;
    bestMatch = item.json;
  }
}

return [{
answer: score >= 4 ? bestMatch.responses : null,
  confidence: score,
  faqs
}];

const rows = $input.all();
const chat = $('When chat message received').first().json;

const staticData = $getWorkflowStaticData('global');

// --- SESSION CHAT ARRAY (NEW) ---
staticData.sessions ??= {};
staticData.sessions[chat.sessionId] ??= { chat: [] };

// push USER message
staticData.sessions[chat.sessionId].chat.push({
  role: "user",
  content: chat.chatInput
});

// keep last 6 messages only
staticData.sessions[chat.sessionId].chat =
  staticData.sessions[chat.sessionId].chat.slice(-6);

// --------------------------------

let bestMatch = null;
let score = 0;
let faqs = "";

const userQ = chat.chatInput.toLowerCase();

for (const item of rows) {
  const q = item.json.prompts;
  const a = item.json.responses;
  if (!q || !a) continue;

  faqs += `Q: ${q}\nA: ${a}\n\n`;

  const hits = q
    .toLowerCase()
    .split(" ")
    .filter(w => userQ.includes(w)).length;

  if (hits > score) {
    score = hits;
    bestMatch = item.json;
  }
}

return [{
  json: {
    sessionId: chat.sessionId,
    chatInput: chat.chatInput,
    faqs,
    confidence: score,
    context: staticData.sessions[chat.sessionId].chat
  }
}];

const staticData = $getWorkflowStaticData("global");
const sessionId = $('When chat message received').first().json.sessionId;

const reply = $input.first().json.content.parts[0].text;

// push ASSISTANT message
staticData.sessions[sessionId].chat.push({
  role: "assistant",
  content: reply
});

// keep last 6
staticData.sessions[sessionId].chat =
  staticData.sessions[sessionId].chat.slice(-6);

return [{
  json: {
    answer: reply
  }
}];
